{
  "query": "query Disponibilidade($procedureId: ID!, $unitId: ID, $dataInicio: String!, $dataFim: String!) {
  disponibilidade(procedureId: $procedureId, unitId: $unitId, dataInicio: $dataInicio, dataFim: $dataFim) {
    id
    dataHora
    capacity
    booked
    remainingCapacity
    schedule {
      unit { nome address cnes }
      provider { nome crm especialidade }
    }
  }
}",
  "variables": {
    "procedureId": "{{procedureId}}",
    "unitId": "{{unitId}}",
    "dataInicio": "2026-07-01",
    "dataFim": "2026-07-07"
  }
}

{
  "query": "query Agendamentos($pacienteId: ID, $unitId: ID, $status: AppointmentStatus, $dateFrom: String!, $dateTo: String!) {
  agendamentos(pacienteId: $pacienteId, unitId: $unitId, status: $status, dateFrom: $dateFrom, dateTo: $dateTo) {
    id
    status
    expiresAt
    slot {
      dataHora
      schedule {
        unit { nome address }
        provider { nome especialidade }
      }
    }
    cancellationReason
  }
}",
  "variables": {
    "pacienteId": "{{patientId}}",
    "status": "CONFIRMADO",
    "dateFrom": "2026-07-01",
    "dateTo": "2026-07-31"
  }
}

{
  "query": "query Agendamento($id: ID!) {
  agendamento(id: $id) {
    id
    status
    expiresAt
    slot {
      dataHora
      schedule {
        unit { nome address phone }
        provider { nome crm especialidade }
      }
    }
  }
}",
  "variables": {
    "id": "{{appointmentId}}"
  }
}

{
  "query": "query Grade($unitId: ID!, $week: String!) {
  grade(unitId: $unitId, week: $week) {
    id
    dayOfWeek
    startTime
    endTime
    slotDurationMin
    capacity
    active
    provider { nome especialidade }
  }
}",
  "variables": {
    "unitId": "{{unitId}}",
    "week": "2026-07-07"
  }
}
